import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Category","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/category.md","filePath":"03-developer/models/category.md"}`),a={name:`03-developer/models/category.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="category" tabindex="-1">Category <a class="header-anchor" href="#category" aria-label="Permalink to “Category”">​</a></h1><p>Model reference · <code>App\\Models\\Category</code></p><h3 id="_1-model" tabindex="-1">1. Model <a class="header-anchor" href="#_1-model" aria-label="Permalink to “1. Model”">​</a></h3><p>The product category management model; includes the category tree structure, appearance settings, relationships with products, and SEO and Schema Markup settings.</p><h3 id="_2-table-categories" tabindex="-1">2. Table: <code>categories</code> <a class="header-anchor" href="#_2-table-categories" aria-label="Permalink to “2. Table: categories”">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Comment</th></tr></thead><tbody><tr><td><code>id</code></td><td>bigint unsigned</td><td>No</td><td>Category ID</td></tr><tr><td><code>name</code></td><td>text</td><td>No</td><td>Category name</td></tr><tr><td><code>slug</code></td><td>varchar(128)</td><td>No</td><td>Unique text identifier for the URL</td></tr><tr><td><code>subtitle</code></td><td>text</td><td>Yes</td><td>Category subtitle</td></tr><tr><td><code>icon</code></td><td>varchar(255)</td><td>Yes</td><td>Category icon</td></tr><tr><td><code>description</code></td><td>longtext</td><td>Yes</td><td>Category description</td></tr><tr><td><code>sort</code></td><td>int</td><td>No</td><td>Display order</td></tr><tr><td><code>image</code></td><td>varchar(2048)</td><td>Yes</td><td>Category image path</td></tr><tr><td><code>svg</code></td><td>varchar(2048)</td><td>Yes</td><td>SVG vector image path</td></tr><tr><td><code>bg</code></td><td>varchar(2048)</td><td>Yes</td><td>Background image path</td></tr><tr><td><code>parent_id</code></td><td>int unsigned</td><td>Yes</td><td>Parent category ID</td></tr><tr><td><code>theme</code></td><td>longtext (JSON)</td><td>Yes</td><td>Category-specific Theme settings</td></tr><tr><td><code>canonical</code></td><td>text</td><td>Yes</td><td>Canonical URL for SEO</td></tr><tr><td><code>hide</code></td><td>tinyint(1)</td><td>No</td><td>Whether to hide in subcategory menus</td></tr><tr><td><code>deleted_at</code></td><td>timestamp</td><td>Yes</td><td>Soft deletion time</td></tr><tr><td><code>created_at</code></td><td>timestamp</td><td>Yes</td><td>Creation time</td></tr><tr><td><code>updated_at</code></td><td>timestamp</td><td>Yes</td><td>Last modification time</td></tr><tr><td><code>default_markup</code></td><td>text</td><td>Yes</td><td>Default Schema Markup for descendant products</td></tr><tr><td><code>markups</code></td><td>text</td><td>Yes</td><td>Schema Markup for the category page</td></tr></tbody></table><h3 id="_3-extra-description-of-table-fields" tabindex="-1">3. Extra description of table fields <a class="header-anchor" href="#_3-extra-description-of-table-fields" aria-label="Permalink to “3. Extra description of table fields”">​</a></h3><p><strong><code>categories.name</code>, <code>categories.subtitle</code>, and <code>categories.description</code></strong></p><p>Store the category name, subtitle, and description. All three fields support multiple languages.</p><p><strong><code>categories.slug</code></strong></p><p>The category&#39;s unique text identifier, used to address pages.</p><p><strong><code>categories.icon</code></strong></p><p>Stores the name of the icon selected through the Remix Icon collection&#39;s Icon Picker.</p><p><strong><code>categories.sort</code></strong></p><p>Specifies the category&#39;s display order.</p><p><strong><code>categories.image</code>, <code>categories.svg</code>, and <code>categories.bg</code></strong></p><ul><li><code>image</code>: Category image.</li><li><code>svg</code>: Category vector image, which can be used alongside the main image.</li><li><code>bg</code>: Category background image, which can be used in the design of various Theme sections.</li></ul><p><strong><code>categories.parent_id</code></strong></p><p>Used to create a category tree structure. This field stores the parent category ID and can be <code>NULL</code> for top-level categories.</p><p><strong><code>categories.theme</code></strong></p><p>Makes it possible to define Theme settings specific to a category. This feature can distinguish the category&#39;s appearance from the site&#39;s general template. Details about the Theme structure and how to use it are explained in the <a href="./area.html">Area</a> documentation.</p><p><strong><code>categories.canonical</code></strong></p><p>Stores the page&#39;s Canonical URL for managing SEO signals.</p><p><strong><code>categories.hide</code></strong></p><p>Specifies whether the category should be hidden in menus that display subcategories. This field controls menu visibility and does not, by itself, mean that the category page is disabled.</p><p><strong><code>categories.default_markup</code></strong></p><p>Stores the default Schema Markup used for products under this category, particularly when the category serves as the product&#39;s main category.</p><p><strong><code>categories.markups</code></strong></p><p>Stores the Schema Markup for the category page itself. Unlike <code>default_markup</code>, which is used for descendant products, this field is used for the category page&#39;s structured data.</p><h3 id="_4-methods" tabindex="-1">4. Methods <a class="header-anchor" href="#_4-methods" aria-label="Permalink to “4. Methods”">​</a></h3><p><strong><code>markupKeywords()</code></strong></p><p>Returns a list of replacement keywords available for use in Schema Markup, along with each keyword&#39;s title and value. For example, <code>%name%</code> can be replaced with the category name, and <code>app.name</code> retrieves the site name from the application settings.</p><p><strong><code>bgUrl()</code>, <code>imgUrl()</code>, and <code>svgUrl()</code></strong></p><p>Return a usable URL for the background image, main image, or SVG image. If the corresponding image is not available, the site&#39;s default logo is displayed.</p><p><strong><code>bgOriginalUrl()</code> and <code>imgOriginalUrl()</code></strong></p><p>Return the URL for the original versions of the background and category images, unlike regular versions, which may be optimized for display.</p><p><strong><code>children()</code></strong></p><p>Defines a <code>hasMany</code> relationship with this model based on <code>parent_id</code> and returns the descendant categories.</p><p><strong><code>getRouteKeyName()</code></strong></p><p>Specifies that Laravel should use the <code>slug</code> field instead of <code>id</code> for Route Model Binding.</p><p><strong><code>props()</code></strong></p><p>Defines a <code>belongsToMany</code> relationship with the <code>Prop</code> model and returns the props associated with the category. See the <a href="./prop.html">Prop</a> documentation for details.</p><p><strong><code>attachs()</code></strong></p><p>Returns the list of attachments associated with the category.</p><p><strong><code>webUrl()</code></strong></p><p>Returns the category page URL and applies language-related URL adjustments if the site is multilingual.</p><p><strong><code>products()</code></strong></p><p>Defines a <code>belongsToMany</code> relationship with the <code>Product</code> model and returns the products associated with the category.</p><p><strong><code>published($limit = 10, $order = &#39;id&#39;, $dir = &#39;DESC&#39;)</code></strong></p><p>Returns the list of published products under the category. The parameters specify the number of results, the sort field, and the sort direction.</p><p><strong><code>evaluations()</code></strong></p><p>Provides access to the rating system associated with the category. See the <a href="./evaluation.html">Evaluation</a> documentation for details about this system.</p><p><strong><code>parallelCategories()</code></strong></p><p>Returns categories that are parallel to and in the same family as the current category.</p><p><strong><code>markup()</code></strong></p><p>Displays or generates the Schema Markup for the category.</p>`,56)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};